"""Reproducible, source-pixel traces for Olympic and Alveare. No Alhambra geometry copied.
Trace coordinates reference the normalized images generated by this script.
Draft furniture/door offsets are explicitly distinguished from drawing geometry.
"""
from pathlib import Path
from PIL import Image, ImageDraw
import json, math, copy, hashlib, shutil, subprocess
ROOT=Path(__file__).resolve().parents[1]
TMP=ROOT/'work/additional-sites'
TMP.mkdir(parents=True,exist_ok=True)
INPUT=ROOT/'sources/additional-sites'
OUT=ROOT/'public/models'
REF=ROOT/'public/reference/sites'
BASE=json.loads((OUT/'seen-alhambra-planning.json').read_text())
FT=.3048

def area(p):return abs(sum(a[0]*b[1]-b[0]*a[1] for a,b in zip(p,p[1:]+p[:1])))/2

def rect(x1,y1,x2,y2):return [[x1,y1],[x2,y1],[x2,y2],[x1,y2]]

def inside(pt,p):
 x,y=pt;odd=False
 for a,b in zip(p,p[1:]+p[:1]):
  if (a[1]>y)!=(b[1]>y) and x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]:odd=not odd
 return odd

def on_segment(q,a,b):
 return abs((q[0]-a[0])*(b[1]-a[1])-(q[1]-a[1])*(b[0]-a[0]))<.02 and min(a[0],b[0])-.02<=q[0]<=max(a[0],b[0])+.02 and min(a[1],b[1])-.02<=q[1]<=max(a[1],b[1])+.02

class Model:
 def __init__(self,key,name,address,scale,origin,size,outline):
  self.key=key;self.scale=scale;self.origin=origin;self.size=size;self.rawrooms=[];self.level='ground';self.offset=[0,0];self.page=1;self.edges=set();self.objcounter=0
  self.m={k:copy.deepcopy(BASE[k]) for k in ['assets','materials']}
  self.m.update(schemaVersion='2.0',id='seen-'+key,name='Seen Health · '+name,address=address,units='m',coordinateSystem='X right and Z down in the source floor plan; Y up. Geolocation and plan bearing stored separately.',revision='2026-09-22 · Drawing-based model',levels=[],zones=[],rooms=[],walls=[],objects=[],programs=[],referencePages=[],accuracyIssues=[],roofSections=[],details=[],dimensions=[])
  self.m['source']={'title':name+' supplied architectural drawings','date':'August 2026','pages':2 if key=='olympic' else 29,'author':'Twinsteps' if key=='olympic' else 'Steinberg Hart / RIOS / Mannigan','file':f'/reference/sites/{key}/source.pdf'}
  self.m['calibration']={'method':'Printed drawing scale and dimension cross-check','status':'Drawing scale calibrated','pixelsPerMeter':scale,'sourcePixelOrigin':origin,'referencePage':1,'areaPage':1,'anchorAreaSqFt':0,'anchorPolygonPixels':outline,'notes':'Horizontal geometry manually traced from supplied plan. Nominal partitions and approximate opening offsets; field dimensions not verified.'}
  self.m['site']={'image':f'/reference/sites/{key}/plan-ground.jpg','imageSize':size,'bounds':[[-75,-65],[75,65]],'imagePixelBounds':[0,0,*size],'buildingOutline':self.poly(outline),'referencePages':[1],'notes':'Address geocoded by Esri World Geocoding service, September 22 2026. Street topology and adjacent massing reference drawings and public property context; landscape and neighboring heights are indicative.'}
  self.m['facade']={'height':7.8 if key=='olympic' else 27.8,'status':'Estimated from story count; no surveyed elevation supplied','wallMaterial':'wall','glazingMaterial':'glass','referencePages':[1]}
  loc=json.loads((INPUT/f'geocode-{key}.json').read_text())['candidates'][0]['location']
  self.m['location']={'lat':loc['y'],'lng':loc['x'],'status':'Address point; approximate site placement','source':'https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer','planNorthDegrees':0 if key=='alveare' else 32}
  self.m['contextStyle']=key
  self.m['accuracyIssues']=[{'id':'trace','title':'Plan geometry and openings','detail':'Room boundaries are manually traced at the printed drawing scale. Door gaps are approximate and need dimensional coordination. Original per-floor plans can be overlaid in Plan view.','status':'Plan derived','pages':[1,2]},{'id':'fitout','title':'Shared Seen furnishings','detail':'Equipment families, van design and finish palette reuse the approved Alhambra catalog. Positions follow furniture symbols where available; unshown equipment and finishes are design assumptions.','status':'Proposed fit-out','pages':[1,2]},{'id':'context','title':'Surrounding environment','detail':'Geocoded address, named street edges, parking relationship and building story count are supported by sources. Neighboring massing, landscaping, facade details and heights are estimates, not an as-built survey.','status':'Context approximation','pages':[1]}]
 def point(self,p):return [round((p[i]-self.offset[i]-self.origin[i])/self.scale,5) for i in range(2)]
 def poly(self,p):return [self.point(x) for x in p]
 def floor(self,id,name,elev,outline,page,offset=(0,0)):
  self.level=id;self.offset=offset;self.page=page
  self.m['levels'].append({'id':id,'name':name,'elevation':elev,'order':len(self.m['levels']),'referencePages':[page],'elevationStatus':'Estimated' if self.key=='olympic' else 'FF 232.10 ft datum','notes':'Olympic floor-to-floor assumed 3.8 m.' if self.key=='olympic' else 'Local model datum; small ramp/room elevation differences remain approximate.','planImage':f'/reference/sites/{self.key}/plan-{id}.jpg','planOrigin':[self.origin[i]+offset[i] for i in range(2)],'planImageSize':self.size,'planPixelsPerMeter':self.scale})
  p=self.poly(outline)
  self.m['zones'].append({'id':id+'-floor','name':name,'short':name,'color':'#59988b' if id=='ground' else '#bc9963','levelId':id,'polygon':p,'referencePages':[page],'floorMaterial':'wood','notes':'Source-calibrated floor plate. Select individual rooms for details.','publishedAreaSqFt':None,'tracedFootprintSqFt':round(area(p)/FT**2,1),'programId':id,'wallHeight':3.05 if id=='ground' else 2.85,'wallHeightStatus':'Nominal; verify against elevations','geometryStatus':'Manually traced from architectural plan','spread':[0,0]})
 def wall(self,a,b):
  a=self.point(a);b=self.point(b)
  tag=(self.level,*sorted((tuple(a),tuple(b))))
  if tag in self.edges or math.dist(a,b)<.05:return
  self.edges.add(tag)
  self.m['walls'].append({'id':f'w-{len(self.m["walls"])}','zoneId':self.level+'-floor','levelId':self.level,'a':a,'b':b,'height':3.05 if self.level=='ground' else 2.85,'thickness':.13,'material':'wall','status':'Plan traced; nominal partition thickness','referencePages':[self.page]})
 def room(self,id,name,bounds,kind,door=None,area_sf=None):
  p=rect(*bounds) if len(bounds)==4 and isinstance(bounds[0],(int,float)) else bounds
  rid=self.level+'-'+id
  material={'bath':'wet-tile','shower':'wet-tile','kitchen':'tile','rehab':'sports','office':'carpet','conference':'carpet','exam':'vinyl','support':'tile','outdoor':'concrete'}.get(kind,'wood')
  if id=='parking':material='concrete'
  r={'id':rid,'name':name,'zoneId':self.level+'-floor','levelId':self.level,'polygon':self.poly(p),'kind':kind,'referencePages':[self.page],'status':'Plan traced','notes':(f'Published room area: {area_sf} SF. ' if area_sf else '')+'Boundary follows supplied drawing; heights and furniture dimensions use the shared Seen library.','floorMaterial':material}
  self.m['rooms'].append(r);self.rawrooms.append((r,p,self.offset,self.page))
  if door is not None:
   for i,(a,b) in enumerate(zip(p,p[1:]+p[:1])):
    if i==door:
     length=math.dist(a,b);gap=min(self.scale*.98,length*.55);t=(length-gap)/length/2
     self.wall(a,[a[j]+(b[j]-a[j])*t for j in range(2)])
     self.wall([a[j]+(b[j]-a[j])*(1-t) for j in range(2)],b)
    else:self.wall(a,b)
  return r
 def asset(self,id,kind,dims,mat='oak',**kw):self.m['assets'][id]={'kind':kind,'dimensions':dims,'material':mat,**kw}
 def obj(self,asset,x,y,room=None,rot=0,scale=(1,1,1),height=0,layer='furniture'):
  p=self.point([x,y]);rid=room['id'] if isinstance(room,dict) else room;self.objcounter+=1
  self.m['objects'].append({'id':self.key+'-obj-'+str(self.objcounter),'assetId':asset,'zoneId':self.level+'-floor' if self.level!='site' else 'site','levelId':self.level,'position':[p[0],height,p[1]],'rotation':rot,'scale':list(scale),'roomId':rid,'referencePages':[self.page],'status':'Shared asset / approximate placement','notes':'Seen catalog reused; plan-related placement.','layer':layer})
 def furnish(self):
  self.asset('site-meeting','table',[1.2,.75,2.1],'photo-marble')
  for r,p,offset,page in self.rawrooms:
   self.level=r['levelId'];self.offset=offset;self.page=page
   xs=[a[0] for a in p];ys=[a[1] for a in p];l,t,rr,b=min(xs),min(ys),max(xs),max(ys);cx=(l+rr)/2;cy=(t+b)/2;s=self.scale
   k=r['kind'];w=(rr-l)/s;d=(b-t)/s
   def put(a,x,y,rot=0,scale=(1,1,1),h=0):
    if inside((x,y),p):self.obj(a,x,y,r,rot,scale,h)
   if k in ('exam','evaluation'):
    put('interior-exam-chair',cx,cy);put('interior-stool',cx+.85*s,cy+.5*s);put('interior-exam-sink',l+.85*s,b-.38*s);put('interior-cart',rr-.4*s,t+.6*s)
   elif k=='bath':
    put('toilet',rr-.45*s,t+.45*s);put('basin',l+.45*s,b-.35*s)
   elif k=='shower':
    put('access-shower',cx,t+.8*s);put('basin',l+.45*s,b-.4*s);put('bench',cx,b-.45*s,scale=(.7,1,1))
   elif k in ('office','counsel','treatment'):
    put('desk',cx,t+.65*s);put('photo-clinic-task-chair',cx,t+1.4*s);put('photo-dining-chair',cx,b-.7*s);put('cabinet',rr-.35*s,cy,math.pi/2)
   elif k=='conference':
    put('site-meeting',cx,cy)
    for dy in [-.55,.55]:
     put('photo-dining-chair',cx-.95*s,cy+dy*s,math.pi/2);put('photo-dining-chair',cx+.95*s,cy+dy*s,-math.pi/2)
   elif k=='laundry':
    put('access-laundry',l+.5*s,t+.5*s);put('access-laundry',l+1.3*s,t+.5*s);put('access-linen-rack',cx,b-.35*s)
   elif k=='kitchen':
    for xx in [l+1.1*s,l+2.8*s]:put('counter',xx,b-.4*s)
    put('counter',cx,cy);put('refrigerator',rr-.55*s,t+.6*s);put('upperfit-storage-rack',l+1*s,t+.4*s)
   elif k=='storage':
    put('upperfit-storage-rack',cx,t+.45*s)
    if d>2.7:put('upperfit-storage-rack',cx,b-.4*s)
   elif k=='quiet':
    put('photo-lounge-chair',l+.8*s,cy);put('photo-lounge-chair',rr-.8*s,cy);put('plan-lounge-table',cx,cy+.7*s)
   elif k=='rehab':
    for xx in [l+1.0*s,l+2.7*s]:put('interior-plinth',xx,t+1.4*s)
    if w>5 and d>4:
     put('interior-bars',rr-1.3*s,cy,0);put('interior-stepper',l+1*s,b-1*s);put('interior-stepper',l+2.4*s,b-1*s);put('interior-rehab-rack',rr-.65*s,b-.6*s)
   elif k in ('day','dining','activity','memory'):
    spacing=2.65*s
    for y in range(round(t+1.6*s),round(b-1.1*s),round(spacing)):
     for x in range(round(l+1.55*s),round(rr-1.1*s),round(spacing)):
      # Entire table/chair group must sit inside this room and outside enclosed rooms.
      corners=[(x+dx*s,y+dy*s) for dx,dy in [(-1,-1),(1,-1),(1,1),(-1,1)]]
      blockers=[rp for other,rp,_,_ in self.rawrooms if other['id']!=r['id'] and other['levelId']==r['levelId'] and other['kind'] not in ['circulation','day','dining','activity']]
      if not all(inside(c,p) and not any(inside(c,q) for q in blockers) for c in corners):continue
      put('interior-plan-dining-table',x,y)
      for dx,dy,rot in [(0,-.88,math.pi),(0,.88,0),(-.88,0,-math.pi/2),(.88,0,math.pi/2)]:put('photo-dining-chair',x+dx*s,y+dy*s,rot)
   elif k=='reception':
    put('photo-reception-long',cx,cy);put('photo-clinic-task-chair',cx,cy-.65*s)
   elif k=='waiting':
    for xx in [l+.65*s,l+1.4*s,l+2.15*s]:put('photo-dining-chair',xx,t+.6*s)
   elif k in ('admin','work'):
    for y in range(round(t+1.1*s),round(b-.8*s),round(2.15*s)):
     for x in range(round(l+1.0*s),round(rr-.7*s),round(1.65*s)):
      put('upperfit-desk-blue',x,y);put('upperfit-chair',x,y+.7*s)
   elif k=='training':
    for y in range(round(t+1*s),round(b-.9*s),round(1.9*s)):
     for x in range(round(l+1.1*s),round(rr-.8*s),round(1.8*s)):
      put('desk',x,y);put('upperfit-chair',x,y+.6*s)
   elif k=='break':
    put('photo-staff-casework',cx,b-.4*s);put('refrigerator',l+.5*s,b-.55*s)
    put('site-meeting',cx,cy-.5*s)
    for dx in [-1,1]:
     for dy in [-.6,.5]:put('photo-dining-chair',cx+dx*s,cy+dy*s-.5*s,-dx*math.pi/2)
 def finish(self,outline,extra):
  self.level='ground';self.offset=[0,0];self.page=1
  self.m.update(extra)
  used={o['assetId'] for o in self.m['objects']};self.m['assets']={k:v for k,v in self.m['assets'].items() if k in used}
  self.m['roofSections']=[{'id':'main-roof','kind':'flat','bounds':[self.point([min(x[0] for x in outline),min(x[1] for x in outline)]),self.point([max(x[0] for x in outline),max(x[1] for x in outline)])],'eaveHeight':7.8 if self.key=='olympic' else 27.8,'rise':.12,'referencePages':[1],'status':'Estimated height','polygon':self.poly(outline),'parapet':True}]
  self.m['envelope']={'walls':[],'loops':[],'notes':'Schematic facade openings based on plan window rhythm. Dimensions and finishes require elevation confirmation.'}
  for i,(aa,bb) in enumerate(zip(outline,outline[1:]+outline[:1])):
   pa,pb=self.point(aa),self.point(bb);length=math.dist(pa,pb);wid='shell-'+str(i);openings=[]
   h=7.8 if self.key=='olympic' else 4.2
   if length>4:
    for j in range(int((length-1.2)/3)):
     for sill in ([.7,4.5] if self.key=='olympic' else [.25]):
      openings.append({'id':wid+'-window-'+str(j)+'-'+str(sill),'offset':.7+j*3,'width':2.0,'sill':sill,'height':1.9 if self.key=='olympic' else 2.8,'kind':'window','material':'glass'})
   self.m['envelope']['walls'].append({'id':wid,'zoneId':'ground-floor','a':pa,'b':pb,'height':h,'thickness':.2,'material':'wall','openings':openings,'status':'Indicative facade; plan outline exact to trace','referencePages':[1]})
  self.m['envelope']['loops']=[{'id':'perimeter','wallIds':[w['id'] for w in self.m['envelope']['walls']]}]
  # Preserve perimeter cutaways, and let the envelope replace them in exterior view.
  for wall in self.m['walls']:
   if any(on_segment(wall['a'],pa,pb) and on_segment(wall['b'],pa,pb) for pa,pb in zip(self.m['site']['buildingOutline'],self.m['site']['buildingOutline'][1:]+self.m['site']['buildingOutline'][:1])):
    wall['status']='Exterior perimeter / plan traced'
  self.m['exportFiles']={'glb':f'/models/seen-{self.key}.glb','audit':'/models/additional-sites-accuracy.md'}
  (OUT/f'seen-{self.key}.json').write_text(json.dumps(self.m,indent=2)+'\n')
  for lev in self.m['levels']:
   im=Image.open(REF/self.key/f'plan-{lev["id"]}.jpg').convert('RGBA');draw=ImageDraw.Draw(im)
   for r,p,offset,page in self.rawrooms:
    if r['levelId']!=lev['id']:continue
    draw.line([tuple(q) for q in p+[p[0]]],fill=(220,40,40,230),width=2)
   im.convert('RGB').save(TMP/f'{self.key}-{lev["id"]}-audit.jpg')
  print(self.key,len(self.m['rooms']),'rooms',len(self.m['walls']),'wall segments',len(self.m['objects']),'objects')

def source(key,files):
 d=REF/key;d.mkdir(parents=True,exist_ok=True)
 manifest=[]
 for name,file in files:
  src=d/name
  if not src.exists():
   src=Path.home()/'Downloads'/file;shutil.copy2(src,d/name)
  manifest.append({'file':name,'original':file,'sha256':hashlib.sha256(src.read_bytes()).hexdigest()})
 (d/'manifest.json').write_text(json.dumps(manifest,indent=2))

